20	import * as graphic from '../../util/graphic';
21	import LineGroup from './Line';
22	import SeriesData from '../../data/SeriesData';
23	import {
24	    StageHandlerProgressParams,
25	    LineStyleOption,
26	    LineLabelOption,
27	    ColorString,
28	    AnimationOptionMixin,
29	    ZRStyleProps,
30	    StatesOptionMixin,
31	    DisplayState,
32	    LabelOption,
33	    DefaultEmphasisFocus,
34	    BlurScope
35	} from '../../util/types';
36	import Displayable from 'zrender/src/graphic/Displayable';
37	import Model from '../../model/Model';
38	import { getLabelStatesModels } from '../../label/labelStyle';
39	import Element from 'zrender/src/Element';
40	
41	interface LineLike extends graphic.Group {
42	    updateData(data: SeriesData, idx: number, scope?: LineDrawSeriesScope): void
43	    updateLayout(data: SeriesData, idx: number): void
44	    fadeOut?(cb: () => void): void
45	}
46	
47	interface LineLikeCtor {
48	    new(data: SeriesData, idx: number, scope?: LineDrawSeriesScope): LineLike
49	}
50	
51	interface LineDrawStateOption {
52	    lineStyle?: LineStyleOption
53	    label?: LineLabelOption
54	}
55	
56	export interface LineDrawModelOption extends LineDrawStateOption,
57	    StatesOptionMixin<LineDrawStateOption, {
58	        emphasis?: {
59	            focus?: DefaultEmphasisFocus
60	        }
61	    }> {
62	    // If has effect
63	    effect?: {
64	        show?: boolean
65	        period?: number
66	        delay?: number | ((idx: number) => number)
67	        /**
68	         * If move with constant speed px/sec
69	         * period will be ignored if this property is > 0,
70	         */
71	        constantSpeed?: number
72	
73	        symbol?: string
74	        symbolSize?: number | number[]
75	        loop?: boolean
76	        roundTrip?: boolean
77	        /**
78	         * Length of trail, 0 - 1
79	         */
80	        trailLength?: number
81	        /**
82	         * Default to be same with lineStyle.color
83	         */
84	        color?: ColorString
85	    }
86	}
87	
88	type ListForLineDraw = SeriesData<Model<LineDrawModelOption & AnimationOptionMixin>>;
89	
90	export interface LineDrawSeriesScope {
91	    lineStyle?: ZRStyleProps
92	    emphasisLineStyle?: ZRStyleProps
93	    blurLineStyle?: ZRStyleProps
94	    selectLineStyle?: ZRStyleProps
95	
96	    labelStatesModels: Record<DisplayState, Model<LabelOption>>
97	
98	    focus?: DefaultEmphasisFocus
99	    blurScope?: BlurScope
100	    emphasisDisabled?: boolean;
101	}
102	
103	class LineDraw {
104	    group = new graphic.Group();
105	
106	    private _LineCtor: LineLikeCtor;
107	
108	    private _lineData: ListForLineDraw;
109	
110	    private _seriesScope: LineDrawSeriesScope;
111	
112	    private _progressiveEls: LineLike[];
113	
114	    constructor(LineCtor?: LineLikeCtor) {
115	        this._LineCtor = LineCtor || LineGroup;
116	    }
117	
118	    updateData(lineData: ListForLineDraw) {
119	        // Remove progressive els.
120	        this._progressiveEls = null;
121	
122	        const lineDraw = this;
123	        const group = lineDraw.group;
124	
125	        const oldLineData = lineDraw._lineData;
126	        lineDraw._lineData = lineData;
127	
128	        // There is no oldLineData only when first rendering or switching from
129	        // stream mode to normal mode, where previous elements should be removed.
130	        if (!oldLineData) {
131	            group.removeAll();
132	        }
133	
134	        const seriesScope = makeSeriesScope(lineData);
135	
136	        lineData.diff(oldLineData)
137	            .add((idx) => {
138	                this._doAdd(lineData, idx, seriesScope);
139	            })
140	            .update((newIdx, oldIdx) => {
141	                this._doUpdate(oldLineData, lineData, oldIdx, newIdx, seriesScope);
142	            })
143	            .remove((idx) => {
144	                group.remove(oldLineData.getItemGraphicEl(idx));
145	            })
146	            .execute();
147	    };
148	
149	    updateLayout() {
150	        const lineData = this._lineData;
151	
152	        // Do not support update layout in incremental mode.
153	        if (!lineData) {
154	            return;
155	        }
156	
157	        lineData.eachItemGraphicEl(function (el: LineLike, idx) {
158	            el.updateLayout(lineData, idx);
159	        }, this);
160	    };
161	
162	    incrementalPrepareUpdate(lineData: ListForLineDraw) {
163	        this._seriesScope = makeSeriesScope(lineData);
164	        this._lineData = null;
165	        this.group.removeAll();
166	    };
167	
168	    incrementalUpdate(taskParams: StageHandlerProgressParams, lineData: ListForLineDraw) {
169	
170	        this._progressiveEls = [];
171	
172	        function updateIncrementalAndHover(el: Displayable) {
173	            if (!el.isGroup && !isEffectObject(el)) {
174	                el.incremental = true;
175	                el.ensureState('emphasis').hoverLayer = true;
176	            }
177	        }
178	
179	        for (let idx = taskParams.start; idx < taskParams.end; idx++) {
180	            const itemLayout = lineData.getItemLayout(idx);
181	
182	            if (lineNeedsDraw(itemLayout)) {
183	                const el = new this._LineCtor(lineData, idx, this._seriesScope);
184	                el.traverse(updateIncrementalAndHover);
185	
186	                this.group.add(el);
187	                lineData.setItemGraphicEl(idx, el);
188	
189	                this._progressiveEls.push(el);
190	            }
191	        }
192	    };
193	
194	    remove() {
195	        this.group.removeAll();
196	    };
197	
198	    eachRendered(cb: (el: Element) => boolean | void) {
199	        graphic.traverseElements(this._progressiveEls || this.group, cb);
200	    }
201	
202	    private _doAdd(
203	        lineData: ListForLineDraw,
204	        idx: number,
205	        seriesScope: LineDrawSeriesScope
206	    ) {
207	        const itemLayout = lineData.getItemLayout(idx);
208	
209	        if (!lineNeedsDraw(itemLayout)) {
210	            return;
211	        }
212	
213	        const el = new this._LineCtor(lineData, idx, seriesScope);
214	        lineData.setItemGraphicEl(idx, el);
215	        this.group.add(el);
216	    }
217	    private _doUpdate(
218	        oldLineData: ListForLineDraw,
219	        newLineData: ListForLineDraw,
220	        oldIdx: number,
221	        newIdx: number,
222	        seriesScope: LineDrawSeriesScope
223	    ) {
224	        let itemEl = oldLineData.getItemGraphicEl(oldIdx) as LineLike;
225	
226	        if (!lineNeedsDraw(newLineData.getItemLayout(newIdx))) {
227	            this.group.remove(itemEl);
228	            return;
229	        }
230	
231	        if (!itemEl) {
232	            itemEl = new this._LineCtor(newLineData, newIdx, seriesScope);
233	        }
234	        else {
235	            itemEl.updateData(newLineData, newIdx, seriesScope);
236	        }
237	
238	        newLineData.setItemGraphicEl(newIdx, itemEl);
239	
240	        this.group.add(itemEl);
241	    }
242	}
243	
244	function isEffectObject(el: Displayable) {
245	    return el.animators && el.animators.length > 0;
246	}
247	
248	function makeSeriesScope(lineData: ListForLineDraw): LineDrawSeriesScope {
249	    const hostModel = lineData.hostModel;
250	    const emphasisModel = hostModel.getModel('emphasis');
251	    return {
252	        lineStyle: hostModel.getModel('lineStyle').getLineStyle(),
253	        emphasisLineStyle: emphasisModel.getModel(['lineStyle']).getLineStyle(),
254	        blurLineStyle: hostModel.getModel(['blur', 'lineStyle']).getLineStyle(),
255	        selectLineStyle: hostModel.getModel(['select', 'lineStyle']).getLineStyle(),
256	
257	        emphasisDisabled: emphasisModel.get('disabled'),
258	        blurScope: emphasisModel.get('blurScope'),
259	        focus: emphasisModel.get('focus'),
260	
261	        labelStatesModels: getLabelStatesModels(hostModel)
262	    };
263	}
264	
265	function isPointNaN(pt: number[]) {
266	    return isNaN(pt[0]) || isNaN(pt[1]);
267	}
268	
269	function lineNeedsDraw(pts: number[][]) {
270	    return pts && !isPointNaN(pts[0]) && !isPointNaN(pts[1]);
271	}
272	
273	
274	export default LineDraw;

