20	/**
21	 * Line path for bezier and straight line draw
22	 */
23	
24	import * as graphic from '../../util/graphic';
25	import * as vec2 from 'zrender/src/core/vector';
26	import { PathProps } from 'zrender/src/graphic/Path';
27	import { ColorString } from '../../util/types';
28	
29	const straightLineProto = graphic.Line.prototype;
30	const bezierCurveProto = graphic.BezierCurve.prototype;
31	
32	class StraightLineShape {
33	    // Start point
34	    x1 = 0;
35	    y1 = 0;
36	    // End point
37	    x2 = 0;
38	    y2 = 0;
39	
40	    percent = 1;
41	}
42	
43	class CurveShape extends StraightLineShape {
44	    cpx1: number;
45	    cpy1: number;
46	}
47	
48	interface ECLineProps extends PathProps {
49	    shape?: Partial<StraightLineShape | CurveShape>
50	}
51	function isStraightLine(shape: StraightLineShape | CurveShape): shape is StraightLineShape {
52	    return isNaN(+(shape as CurveShape).cpx1) || isNaN(+(shape as CurveShape).cpy1);
53	}
54	
55	class ECLinePath extends graphic.Path<ECLineProps> {
56	
57	    type = 'ec-line';
58	
59	    shape: StraightLineShape | CurveShape;
60	
61	    constructor(opts?: ECLineProps) {
62	        super(opts);
63	    }
64	
65	    getDefaultStyle() {
66	        return {
67	            stroke: '#000',
68	            fill: null as ColorString
69	        };
70	    }
71	
72	    getDefaultShape() {
73	        return new StraightLineShape();
74	    }
75	
76	    buildPath(ctx: CanvasRenderingContext2D, shape: StraightLineShape | CurveShape) {
77	        if (isStraightLine(shape)) {
78	            straightLineProto.buildPath.call(this, ctx, shape);
79	        }
80	        else {
81	            bezierCurveProto.buildPath.call(this, ctx, shape);
82	        }
83	    }
84	
85	    pointAt(t: number) {
86	        if (isStraightLine(this.shape)) {
87	            return straightLineProto.pointAt.call(this, t);
88	        }
89	        else {
90	            return bezierCurveProto.pointAt.call(this, t);
91	        }
92	    }
93	
94	    tangentAt(t: number) {
95	        const shape = this.shape;
96	        const p = isStraightLine(shape)
97	            ? [shape.x2 - shape.x1, shape.y2 - shape.y1]
98	            : bezierCurveProto.tangentAt.call(this, t);
99	        return vec2.normalize(p, p);
100	    }
101	
102	}
103	
104	export default ECLinePath;

