20	import { isArray, each } from 'zrender/src/core/util';
21	import * as vector from 'zrender/src/core/vector';
22	import * as symbolUtil from '../../util/symbol';
23	import ECLinePath from './LinePath';
24	import * as graphic from '../../util/graphic';
25	import { toggleHoverEmphasis, enterEmphasis, leaveEmphasis, SPECIAL_STATES } from '../../util/states';
26	import {getLabelStatesModels, setLabelStyle} from '../../label/labelStyle';
27	import {round} from '../../util/number';
28	import SeriesData from '../../data/SeriesData';
29	import {
30	    ZRTextAlign,
31	    ZRTextVerticalAlign,
32	    LineLabelOption,
33	    ColorString,
34	    DefaultEmphasisFocus,
35	    BlurScope
36	} from '../../util/types';
37	import SeriesModel from '../../model/Series';
38	import type { LineDrawSeriesScope, LineDrawModelOption } from './LineDraw';
39	import { TextStyleProps } from 'zrender/src/graphic/Text';
40	import { LineDataVisual } from '../../visual/commonVisualTypes';
41	import Model from '../../model/Model';
42	
43	const SYMBOL_CATEGORIES = ['fromSymbol', 'toSymbol'] as const;
44	
45	type ECSymbol = ReturnType<typeof createSymbol>;
46	
47	type LineECSymbol = ECSymbol & {
48	    __specifiedRotation: number
49	};
50	
51	type LineList = SeriesData<SeriesModel, LineDataVisual>;
52	
53	export interface LineLabel extends graphic.Text {
54	    lineLabelOriginalOpacity: number
55	}
56	
57	interface InnerLineLabel extends LineLabel {
58	    __align: TextStyleProps['align']
59	    __verticalAlign: TextStyleProps['verticalAlign']
60	    __position: LineLabelOption['position']
61	    __labelDistance: number[]
62	}
63	
64	function makeSymbolTypeKey(symbolCategory: 'fromSymbol' | 'toSymbol') {
65	    return '_' + symbolCategory + 'Type' as '_fromSymbolType' | '_toSymbolType';
66	}
67	function makeSymbolTypeValue(name: 'fromSymbol' | 'toSymbol', lineData: LineList, idx: number) {
68	    const symbolType = lineData.getItemVisual(idx, name);
69	    if (!symbolType || symbolType === 'none') {
70	        return symbolType;
71	    }
72	    const symbolSize = lineData.getItemVisual(idx, name + 'Size' as 'fromSymbolSize' | 'toSymbolSize');
73	    const symbolRotate = lineData.getItemVisual(idx, name + 'Rotate' as 'fromSymbolRotate' | 'toSymbolRotate');
74	    const symbolOffset = lineData.getItemVisual(idx, name + 'Offset' as 'fromSymbolOffset' | 'toSymbolOffset');
75	    const symbolKeepAspect = lineData.getItemVisual(idx,
76	        name + 'KeepAspect' as 'fromSymbolKeepAspect' | 'toSymbolKeepAspect');
77	    const symbolSizeArr = symbolUtil.normalizeSymbolSize(symbolSize);
78	
79	    const symbolOffsetArr = symbolUtil.normalizeSymbolOffset(symbolOffset || 0, symbolSizeArr);
80	
81	    return symbolType + symbolSizeArr + symbolOffsetArr + (symbolRotate || '') + (symbolKeepAspect || '');
82	}
83	
84	/**
85	 * @inner
86	 */
87	function createSymbol(name: 'fromSymbol' | 'toSymbol', lineData: LineList, idx: number) {
88	    const symbolType = lineData.getItemVisual(idx, name);
89	    if (!symbolType || symbolType === 'none') {
90	        return;
91	    }
92	
93	    const symbolSize = lineData.getItemVisual(idx, name + 'Size' as 'fromSymbolSize' | 'toSymbolSize');
94	    const symbolRotate = lineData.getItemVisual(idx, name + 'Rotate' as 'fromSymbolRotate' | 'toSymbolRotate');
95	    const symbolOffset = lineData.getItemVisual(idx, name + 'Offset' as 'fromSymbolOffset' | 'toSymbolOffset');
96	    const symbolKeepAspect = lineData.getItemVisual(idx,
97	        name + 'KeepAspect' as 'fromSymbolKeepAspect' | 'toSymbolKeepAspect');
98	
99	    const symbolSizeArr = symbolUtil.normalizeSymbolSize(symbolSize);
100	
101	    const symbolOffsetArr = symbolUtil.normalizeSymbolOffset(symbolOffset || 0, symbolSizeArr);
102	
103	    const symbolPath = symbolUtil.createSymbol(
104	        symbolType,
105	        -symbolSizeArr[0] / 2 + (symbolOffsetArr as number[])[0],
106	        -symbolSizeArr[1] / 2 + (symbolOffsetArr as number[])[1],
107	        symbolSizeArr[0],
108	        symbolSizeArr[1],
109	        null,
110	        symbolKeepAspect
111	    );
112	
113	    (symbolPath as LineECSymbol).__specifiedRotation = symbolRotate == null || isNaN(symbolRotate)
114	        ? void 0
115	        : +symbolRotate * Math.PI / 180 || 0;
116	
117	    symbolPath.name = name;
118	
119	    return symbolPath;
120	}
121	
122	function createLine(points: number[][]) {
123	    const line = new ECLinePath({
124	        name: 'line',
125	        subPixelOptimize: true
126	    });
127	    setLinePoints(line.shape, points);
128	    return line;
129	}
130	
131	function setLinePoints(targetShape: ECLinePath['shape'], points: number[][]) {
132	    type CurveShape = ECLinePath['shape'] & {
133	        cpx1: number
134	        cpy1: number
135	    };
136	
137	    targetShape.x1 = points[0][0];
138	    targetShape.y1 = points[0][1];
139	    targetShape.x2 = points[1][0];
140	    targetShape.y2 = points[1][1];
141	    targetShape.percent = 1;
142	
143	    const cp1 = points[2];
144	    if (cp1) {
145	        (targetShape as CurveShape).cpx1 = cp1[0];
146	        (targetShape as CurveShape).cpy1 = cp1[1];
147	    }
148	    else {
149	        (targetShape as CurveShape).cpx1 = NaN;
150	        (targetShape as CurveShape).cpy1 = NaN;
151	    }
152	}
153	
154	class Line extends graphic.Group {
155	
156	    private _fromSymbolType: string;
157	    private _toSymbolType: string;
158	
159	    constructor(lineData: SeriesData, idx: number, seriesScope?: LineDrawSeriesScope) {
160	        super();
161	        this._createLine(lineData as LineList, idx, seriesScope);
162	    }
163	
164	    _createLine(lineData: LineList, idx: number, seriesScope?: LineDrawSeriesScope) {
165	        const seriesModel = lineData.hostModel;
166	        const linePoints = lineData.getItemLayout(idx);
167	        const line = createLine(linePoints);
168	        line.shape.percent = 0;
169	        graphic.initProps(line, {
170	            shape: {
171	                percent: 1
172	            }
173	        }, seriesModel, idx);
174	
175	        this.add(line);
176	
177	        each(SYMBOL_CATEGORIES, function (symbolCategory) {
178	            const symbol = createSymbol(symbolCategory, lineData, idx);
179	            // symbols must added after line to make sure
180	            // it will be updated after line#update.
181	            // Or symbol position and rotation update in line#beforeUpdate will be one frame slow
182	            this.add(symbol);
183	            this[makeSymbolTypeKey(symbolCategory)] = makeSymbolTypeValue(symbolCategory, lineData, idx);
184	        }, this);
185	
186	        this._updateCommonStl(lineData, idx, seriesScope);
187	    }
188	
189	    // TODO More strict on the List type in parameters?
190	    updateData(lineData: SeriesData, idx: number, seriesScope: LineDrawSeriesScope) {
191	        const seriesModel = lineData.hostModel;
192	
193	        const line = this.childOfName('line') as ECLinePath;
194	        const linePoints = lineData.getItemLayout(idx);
195	        const target = {
196	            shape: {} as ECLinePath['shape']
197	        };
198	
199	        setLinePoints(target.shape, linePoints);
200	        graphic.updateProps(line, target, seriesModel, idx);
201	
202	        each(SYMBOL_CATEGORIES, function (symbolCategory) {
203	            const symbolType = makeSymbolTypeValue(symbolCategory, lineData as LineList, idx);
204	            const key = makeSymbolTypeKey(symbolCategory);
205	            // Symbol changed
206	            if (this[key] !== symbolType) {
207	                this.remove(this.childOfName(symbolCategory));
208	                const symbol = createSymbol(symbolCategory, lineData as LineList, idx);
209	                this.add(symbol);
210	            }
211	            this[key] = symbolType;
212	        }, this);
213	
214	        this._updateCommonStl(lineData, idx, seriesScope);
215	    };
216	
217	    getLinePath() {
218	        return this.childAt(0) as graphic.Line;
219	    }
220	
221	    _updateCommonStl(lineData: SeriesData, idx: number, seriesScope?: LineDrawSeriesScope) {
222	        const seriesModel = lineData.hostModel as SeriesModel;
223	
224	        const line = this.childOfName('line') as ECLinePath;
225	
226	        let emphasisLineStyle = seriesScope && seriesScope.emphasisLineStyle;
227	        let blurLineStyle = seriesScope && seriesScope.blurLineStyle;
228	        let selectLineStyle = seriesScope && seriesScope.selectLineStyle;
229	
230	        let labelStatesModels = seriesScope && seriesScope.labelStatesModels;
231	
232	        let emphasisDisabled = seriesScope && seriesScope.emphasisDisabled;
233	        let focus = (seriesScope && seriesScope.focus) as DefaultEmphasisFocus;
234	        let blurScope = (seriesScope && seriesScope.blurScope) as BlurScope;
235	
236	        // Optimization for large dataset
237	        if (!seriesScope || lineData.hasItemOption) {
238	            const itemModel = lineData.getItemModel<LineDrawModelOption>(idx);
239	            const emphasisModel = itemModel.getModel('emphasis');
240	
241	            emphasisLineStyle = emphasisModel.getModel('lineStyle').getLineStyle();
242	            blurLineStyle = itemModel.getModel(['blur', 'lineStyle']).getLineStyle();
243	            selectLineStyle = itemModel.getModel(['select', 'lineStyle']).getLineStyle();
244	            emphasisDisabled = emphasisModel.get('disabled');
245	            focus = emphasisModel.get('focus');
246	            blurScope = emphasisModel.get('blurScope');
247	
248	            labelStatesModels = getLabelStatesModels(itemModel);
249	        }
250	
251	        const lineStyle = lineData.getItemVisual(idx, 'style');
252	        const visualColor = lineStyle.stroke;
253	
254	        line.useStyle(lineStyle);
255	        line.style.fill = null;
256	        line.style.strokeNoScale = true;
257	
258	        line.ensureState('emphasis').style = emphasisLineStyle;
259	        line.ensureState('blur').style = blurLineStyle;
260	        line.ensureState('select').style = selectLineStyle;
261	
262	        // Update symbol
263	        each(SYMBOL_CATEGORIES, function (symbolCategory) {
264	            const symbol = this.childOfName(symbolCategory) as ECSymbol;
265	            if (symbol) {
266	                // Share opacity and color with line.
267	                symbol.setColor(visualColor);
268	                symbol.style.opacity = lineStyle.opacity;
269	
270	                for (let i = 0; i < SPECIAL_STATES.length; i++) {
271	                    const stateName = SPECIAL_STATES[i];
272	                    const lineState = line.getState(stateName);
273	                    if (lineState) {
274	                        const lineStateStyle = lineState.style || {};
275	                        const state = symbol.ensureState(stateName);
276	                        const stateStyle = state.style || (state.style = {});
277	                        if (lineStateStyle.stroke != null) {
278	                            stateStyle[symbol.__isEmptyBrush ? 'stroke' : 'fill'] = lineStateStyle.stroke;
279	                        }
280	                        if (lineStateStyle.opacity != null) {
281	                            stateStyle.opacity = lineStateStyle.opacity;
282	                        }
283	                    }
284	                }
285	
286	                symbol.markRedraw();
287	            }
288	        }, this);
289	
290	        const rawVal = seriesModel.getRawValue(idx) as number;
291	        setLabelStyle(this, labelStatesModels, {
292	            labelDataIndex: idx,
293	            labelFetcher: {
